あ、ちがうちがう数字は全面的にダメか
```path_with_url(char_u *fname)
{
    char_u *p;

    // We accept alphabetic characters and a dash in scheme part.
    // RFC 3986 allows for more, but it increases the risk of matching
    // non-URL text.

    // first character must be alpha
    if (!isalpha(*fname))
	return 0;

    // check body: alpha or dash
    for (p = fname; (isalpha(*p) || (*p == '-')); ++p)
	;

    // check last char is not a dash
    if (p[-1] == '-')
	return 0;

    // "://" or ":\\" must follow
    return path_is_url(p);
}```

```ts
// ddc_vim_lsp/source.ts
export class Source extends BaseSource {
  async gatherCandidates(
    denops: Denops,
    context: Context,
    _ddcOptions: DdcOptions,
    _sourceOptions: SourceOptions,
    _sourceParams: Record&lt;string, unknown&gt;,
    completeStr: string,
  ): Promise&lt;Candidate[]&gt; {
    return new Promise((resolve) =&gt; {
      // denops.name と 匿名関数の id（=once の戻り値）を渡して ddc_vim_lsp を呼び出す
      denops.call("ddc_vim_lsp#complete", denops.name, once(denops, (response) =&gt; {
        // response は 'aiueo' という文字列
        resolve(toCandidates(response));
      })[0])
    });
  }
}```
